mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select DATE_FORMAT(order_time, '%Y-%m-%d') as date,
COALESCE(sum(amount), 0) as turnover
from orders
where order_time >= #{begin}
and order_time < #{end}
and status = #{status}
group by DATE_FORMAT(order_time, '%Y-%m-%d')

select count(id) from orders


        and order_time >= #{begin}


        and order_time < #{end}


        and status = #{status}

select count(*) as allOrders, sum(case when status = 2 then 1 else 0 end) as waitingOrders, sum(case when status = 3 then 1 else 0 end) as deliveredOrders, sum(case when status = 5 then 1 else 0 end) as completedOrders, sum(case when status = 6 then 1 else 0 end) as cancelledOrders from orders
and order_time >= #{begin}
and order_time < #{end}

select
    COALESCE(sum(amount), 0) as turnover,
    count(*) as validOrderCount
from orders


        and order_time >= #{begin}


        and order_time < #{end}


        and status = #{status}
